// Lab 18.1, provided (you do not edit this file): the two BFS kernels the benchmark compares
// yours with, and the empty kernel that measures what one level costs when nothing is done.
// CUDA; the same file is built for HIP and for the two CPU emulators. The driver tests these
// too, on every graph yours is tested on.
//
//   refBfsPushKernel      book Fig. 18.6 (p. 433), vertex-centric push: one thread per vertex,
//                         every level. On the page the check of level[neighbor] and the store
//                         to it are plain accesses that several threads make at once: a data
//                         race, "benign" only because the writes are idempotent (pp. 433-434),
//                         and undefined behaviour in CUDA's memory model all the same
//                         (notes/today/ch18-facts.md A7). Here every access to level[] and to
//                         the flag is a relaxed atomic: the page's logic, without the race.
//   refBfsFrontierKernel  book Figs. 18.12 and 18.14 (pp. 439-441): one thread per vertex of
//                         the previous frontier, a compare-and-swap to visit, and one
//                         device-scope atomic on the public counter per vertex appended.
//   floorKernel           empty. launchBfsFloor runs the same host loop as the frontier
//                         searches (zero the counter, launch, read the count back) around it.
//
// The page shows no host loop for any of these (notes/ch18.md, "Unclear in the PDF"). The
// launchers are ours.
#include <climits>
#if !defined(__HIPCC__)
#include <cuda/atomic>
#endif

#define UNVISITED UINT_MAX

#ifndef BLOCK_DIM
#define BLOCK_DIM 128
#endif

// On HIP the atomics are the legacy functions (relaxed, valid on global memory,
// notes/today/infra-facts.md B1), not cuda::atomic_ref, as in lab 12.1. Legacy atomics have no
// plain load, so the HIP form of a relaxed load is an atomic add of 0, which returns the value
// atomically at the cost of a read-modify-write. That makes the 'push' row slower on HIP than
// it need be: compare HIP's push times with that in mind.
static __device__ __forceinline__ unsigned int loadRelaxed(unsigned int* address) {
#if defined(__HIPCC__)
    return atomicAdd(address, 0u);
#else
    cuda::atomic_ref<unsigned int, cuda::thread_scope_device> ref(*address);
    return ref.load(cuda::memory_order_relaxed);
#endif
}

static __device__ __forceinline__ void storeRelaxed(unsigned int* address, unsigned int value) {
#if defined(__HIPCC__)
    atomicExch(address, value);
#else
    cuda::atomic_ref<unsigned int, cuda::thread_scope_device> ref(*address);
    ref.store(value, cuda::memory_order_relaxed);
#endif
}

// Fig. 18.14: true for exactly one of the threads that try to visit the same vertex.
static __device__ __forceinline__ unsigned int refVisitVertexAtomically(unsigned int vertex, unsigned int* level,
                                                                       unsigned int currLevel) {
#if defined(__HIPCC__)
    return atomicCAS(&level[vertex], UNVISITED, currLevel) == UNVISITED;   // strong; returns the old value
#else
    cuda::atomic_ref<unsigned int, cuda::thread_scope_device> level_ref(level[vertex]);
    unsigned int unvisited = UNVISITED;
    return level_ref.compare_exchange_strong(unvisited, currLevel, cuda::memory_order_relaxed,
                                             cuda::memory_order_relaxed);
#endif
}

// region: push
__global__ void refBfsPushKernel(const unsigned int* srcPtrs, const unsigned int* dst, unsigned int numVertices,
                                 unsigned int* level, unsigned int* newVertexVisited, unsigned int currLevel) {
    unsigned int vertex = blockIdx.x*blockDim.x + threadIdx.x;
    if(vertex < numVertices) {
        if(loadRelaxed(&level[vertex]) == currLevel - 1) {
            for(unsigned int edge = srcPtrs[vertex]; edge < srcPtrs[vertex + 1]; ++edge) {
                unsigned int neighbor = dst[edge];
                if(loadRelaxed(&level[neighbor]) == UNVISITED) {
                    storeRelaxed(&level[neighbor], currLevel);
                    storeRelaxed(newVertexVisited, 1);
                }
            }
        }
    }
}
// endregion

// region: frontier
__global__ void refBfsFrontierKernel(const unsigned int* srcPtrs, const unsigned int* dst, unsigned int numVertices,
                                     unsigned int* level, unsigned int* prevFrontier, unsigned int* currFrontier,
                                     unsigned int numPrevFrontier, unsigned int* numCurrFrontier,
                                     unsigned int currLevel) {
    unsigned int i = blockIdx.x*blockDim.x + threadIdx.x;
    if(i < numPrevFrontier) {
        unsigned int vertex = prevFrontier[i];
        for(unsigned int edge = srcPtrs[vertex]; edge < srcPtrs[vertex + 1]; ++edge) {
            unsigned int neighbor = dst[edge];
            if(refVisitVertexAtomically(neighbor, level, currLevel)) {
#if defined(__HIPCC__)
                unsigned int currFrontierIdx = atomicAdd(numCurrFrontier, 1u);
#else
                cuda::atomic_ref<unsigned int, cuda::thread_scope_device> numCurrFrontier_ref(*numCurrFrontier);
                unsigned int currFrontierIdx = numCurrFrontier_ref.fetch_add(1, cuda::memory_order_relaxed);
#endif
                currFrontier[currFrontierIdx] = neighbor;
            }
        }
    }
}
// endregion

__global__ void floorKernel() {
}

// Vertex-centric push, one launch per level until a level labels nothing. The caller has set
// level[v] = UNVISITED everywhere except level[root] = 0. Returns the number of launches; the
// last one labels nothing.
unsigned int launchRefBfsPush(const unsigned int* srcPtrs, const unsigned int* dst, unsigned int numVertices,
                              unsigned int* level, unsigned int* newVertexVisited) {
    unsigned int numBlocks = (numVertices + BLOCK_DIM - 1) / BLOCK_DIM;
    unsigned int launches = 0;
    for(unsigned int currLevel = 1; currLevel <= numVertices; ++currLevel) {
        cudaMemset(newVertexVisited, 0, sizeof(unsigned int));
        refBfsPushKernel<<<numBlocks, BLOCK_DIM>>>(srcPtrs, dst, numVertices, level, newVertexVisited, currLevel);
        ++launches;
        unsigned int newVertexVisited_h = 0;
        cudaMemcpy(&newVertexVisited_h, newVertexVisited, sizeof(unsigned int), cudaMemcpyDeviceToHost);
        if(newVertexVisited_h == 0) {
            break;
        }
    }
    return launches;
}

// Frontier push, one launch per level: the same host loop as launchBfsPrivatised in your
// kernel.cu (see there for the contract), around refBfsFrontierKernel.
unsigned int launchRefBfsFrontier(const unsigned int* srcPtrs, const unsigned int* dst, unsigned int numVertices,
                                  unsigned int root, unsigned int* level, unsigned int* frontierA,
                                  unsigned int* frontierB, unsigned int* numCurrFrontier,
                                  unsigned int* frontierSizes) {
    unsigned int* prevFrontier = frontierA;
    unsigned int* currFrontier = frontierB;
    cudaMemcpy(prevFrontier, &root, sizeof(unsigned int), cudaMemcpyHostToDevice);
    unsigned int numPrevFrontier = 1;
    if(frontierSizes) {
        frontierSizes[0] = 1;
    }
    unsigned int launches = 0;
    for(unsigned int currLevel = 1; numPrevFrontier > 0; ++currLevel) {
        cudaMemset(numCurrFrontier, 0, sizeof(unsigned int));
        unsigned int numBlocks = (numPrevFrontier + BLOCK_DIM - 1) / BLOCK_DIM;
        refBfsFrontierKernel<<<numBlocks, BLOCK_DIM>>>(srcPtrs, dst, numVertices, level, prevFrontier,
                                                        currFrontier, numPrevFrontier, numCurrFrontier, currLevel);
        ++launches;
        unsigned int numCurrFrontier_h = 0;
        cudaMemcpy(&numCurrFrontier_h, numCurrFrontier, sizeof(unsigned int), cudaMemcpyDeviceToHost);
        if(frontierSizes) {
            frontierSizes[currLevel] = numCurrFrontier_h;
        }
        if(numCurrFrontier_h > numVertices || currLevel >= numVertices) {
            break;   // impossible for a correct kernel; stop before reading past the buffers
        }
        numPrevFrontier = numCurrFrontier_h;
        unsigned int* tmp = prevFrontier;
        prevFrontier = currFrontier;
        currFrontier = tmp;
    }
    return launches;
}

// The fixed cost of `launches` levels: per level, the counter is zeroed, an empty kernel is
// launched, and the 4-byte count is read back, exactly as the frontier searches do.
void launchBfsFloor(unsigned int launches, unsigned int* numCurrFrontier) {
    for(unsigned int l = 0; l < launches; ++l) {
        cudaMemset(numCurrFrontier, 0, sizeof(unsigned int));
        floorKernel<<<1, BLOCK_DIM>>>();
        unsigned int numCurrFrontier_h = 0;
        cudaMemcpy(&numCurrFrontier_h, numCurrFrontier, sizeof(unsigned int), cudaMemcpyDeviceToHost);
    }
}
